/* ------------------------------------------------------------------ pages (§9) */

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum FieldKind {
    Text,
    Longtext,
    Code,
    Number,
    Boolean,
    Date,
    Datetime,
    Enum,
    Secret,
    /// Round 15 (D414): a time of day (`HH:MM` or `HH:MM:SS`, UTC), with `presets`.
    Time,
    /// Round 15 (D414): a reference to a resource; the value is its id. Choices are `options`; for
    /// a field with `kinds` and no `options` the kernel lists the resources of those kinds.
    Ref,
    /// D477: several of `options` at once; the value is their `value`s joined with `,` in the
    /// order of `options` (so option values never contain a comma). Empty = none chosen.
    Multi,
}

#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct FieldOption {
    pub value: String,
    pub label: Label,
}

#[skip_serializing_none]
#[derive(Debug, Clone, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
#[ts(export, optional_fields)]
pub struct ViewField {
    pub name: String,
    pub label: Label,
    pub kind: FieldKind,
    /// The page value this field edits (§9.3). Resource pages: `name`, `description`,
    /// `tags`, `body.<key>`. Other pages: any name the page's `values` carries.
    /// Unsaved changes, the unsaved mark, ⌘S and "ask before closing" are the frame's job.
    pub bind: Option<String>,
    /// A run parameter: lives in the tab's page state, never saved (I.4).
    pub param: Option<bool>,
    pub options: Option<Vec<FieldOption>>,
    /// Quick values for date / datetime fields.
    pub presets: Option<Vec<FieldOption>>,
    /// code / longtext: take all remaining height (I.7).
    pub fill: Option<bool>,
    /// Language for colouring a code field.
    pub language: Option<String>,
    pub hint: Option<Label>,
    pub placeholder: Option<Label>,
    pub env_value: Option<String>,
    pub env_source: Option<String>,
    pub read_only: Option<bool>,
    /// Round 15 (X4, sqlpool C2): the field must have a value; the shell marks it and refuses
    /// to run (or save) while it is empty. The kernel does not check it.
    pub required: Option<bool>,
    /// Round 15 (sqlpool C2): most characters the shell lets the user type (text fields).
    pub max_length: Option<u32>,
    /// Round 15 (D414): for a `ref` field, the kinds it may point at (full `<pluginId>:<kind>`, or
    /// the page's own plugin's short name).
    pub kinds: Option<Vec<String>>,
    /// Round 21 (D462): writing help for this field. Absent = the shell offers it on editable
    /// `text`, `longtext` and `code` fields whenever an assist provider is installed.
    #[serde(default)]
    pub assist: Option<FieldAssist>,
    /// D482: set by the kernel (never by a plugin) on a bound field whose kind declares it `refs: true`: `[[…]]`
    /// written in it are references, and the interface offers the candidates while typing.
    #[serde(default)]
    pub refs: Option<bool>,
}

/// Round 21 (D462, docs/redesign/ai-assist.md §5): how the shell's writing help treats one field.
#[skip_serializing_none]
#[derive(Debug, Clone, Default, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
#[ts(export, optional_fields)]
pub struct FieldAssist {
    /// `true`: no writing help on this field.
    pub off: Option<bool>,
    /// What the field should contain, for the helper (e.g. "a read-only SQL query").
    pub hint: Option<Label>,
    /// `text` | `markdown` | `json` | `code:<language>`; absent = from the field kind.
    pub format: Option<String>,
}

