#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn wire_shapes_are_stable() {
        let node = ViewNode::Form {
            id: "f".into(),
            layout: FormLayout::Stack,
            label: None,
            fields: vec![ViewField {
                name: "text".into(),
                label: Label::Text("Text".into()),
                kind: FieldKind::Longtext,
                bind: Some("body.text".into()),
                param: None,
                options: None,
                presets: None,
                fill: Some(true),
                language: None,
                hint: None,
                placeholder: None,
                env_value: None,
                env_source: None,
                read_only: None,
                required: None,
                max_length: None,
                kinds: None,
                assist: None,
                refs: None,
            }],
        };
        assert_eq!(
            serde_json::to_value(&node).unwrap(),
            json!({ "type": "form", "id": "f", "layout": "stack",
                    "fields": [{ "name": "text", "label": "Text", "kind": "longtext", "bind": "body.text", "fill": true }] })
        );
        let effect = CommandEffect::PickFolder { plugin: "p".into(), replace: None };
        assert_eq!(serde_json::to_value(&effect).unwrap(), json!({ "type": "pick-folder", "plugin": "p" }));
        assert_eq!(serde_json::to_value(NodeState::MissingPlugin).unwrap(), json!("missing-plugin"));
        assert_eq!(serde_json::to_value(ErrorCode::WorkerGone).unwrap(), json!("workerGone"));
        let label: Label = serde_json::from_value(json!({ "en-US": "Note", "zh-CN": "笔记" })).unwrap();
        assert!(matches!(label, Label::Localized(_)));
    }

    #[test]
    fn round11_wire_shapes() {
        let e = serde_json::to_value(CommandEffect::OpenExternal { url: "https://a.test".into() }).unwrap();
        assert_eq!(e, json!({ "type": "openExternal", "url": "https://a.test" }));
        let t: ViewNode = serde_json::from_value(json!({ "type": "text", "id": "t", "text": "# x", "format": "markdown" })).unwrap();
        assert_eq!(serde_json::to_value(&t).unwrap()["format"], "markdown");
        assert!(serde_json::from_value::<ViewNode>(json!({ "type": "text", "id": "t", "text": "x", "format": "html" })).is_err());
        let plain: ViewNode = serde_json::from_value(json!({ "type": "text", "id": "t", "text": "x" })).unwrap();
        assert!(serde_json::to_value(&plain).unwrap().get("format").is_none());
        let l = LanguageInfo { locale: SHELL_LOCALE.into(), name: "English".into(), plugin: None };
        assert_eq!(serde_json::to_value(l).unwrap(), json!({ "locale": "en-US", "name": "English" }));
        let w: WorkspaceInfo = serde_json::from_value(json!({ "id": "w", "name": "n" })).unwrap();
        assert!(w.startup_pages.is_none());
    }

    #[test]
    fn round13_wire_shapes() {
        let e = WorkspaceEntry { id: "w".into(), name: "n".into(), folder: "f".into(), last_opened: None, current: true };
        assert_eq!(serde_json::to_value(e).unwrap(), json!({ "id": "w", "name": "n", "folder": "f", "current": true }));
        let s: WorkspaceSettingsSnapshot = serde_json::from_value(json!({})).unwrap();
        assert_eq!(s, WorkspaceSettingsSnapshot::default());
        let p = SnapshotParam { name: "ui.theme".into(), param_type: ParamType::Text, value: "dark".into() };
        assert_eq!(serde_json::to_value(p).unwrap(), json!({ "name": "ui.theme", "type": "text", "value": "dark" }));
    }

    #[test]
    fn plugin_views_with_unknown_fields_are_rejected() {
        let bad = json!({ "type": "text", "id": "t", "text": "x", "style": "color:red" });
        assert!(serde_json::from_value::<ViewNode>(bad).is_err());
        let unknown = json!({ "type": "iframe", "id": "t" });
        assert!(serde_json::from_value::<ViewNode>(unknown).is_err());
    }

    #[test]
    fn request_without_params_or_client_parses() {
        let r: Request = serde_json::from_str(r#"{"id":1,"method":"tree.list"}"#).unwrap();
        assert!(r.params.is_null() && r.client.is_none());
    }
}
